
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_mn15_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_mn15", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.627211989972016e-01, -1.602761460103315e-01, -1.565794103131734e-01, -1.508010383242774e-01, -1.413404528502954e-01, -1.250761016134766e-01, -9.652931874282981e-02, -4.917372993658781e-02, 1.686701836938868e-02, 8.340914987407633e-02, 8.139937129375230e-02, -7.037371323053514e-02, -4.735596033255349e-02, -2.770396760353540e-02, 1.112059748228685e-02, 3.871176279671537e-02, 1.106155138119521e-02, -1.258626257107345e-03, -6.370029040244535e-04, -9.278616144866421e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


